INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", "2030/12/17 14:59:59", 24, "アヤネ", 0, 10046, 0, 102301, "2020/07/31 12:00:00", 2, 24001, 401, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", "2030/12/17 14:59:59", 24, "アヤネ", 0, 10046, 2.21, 102301, "2020/07/31 12:00:00", 1, 24002, 402, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", "2030/12/17 14:59:59", 24, "アヤネ", 0, 10046, 0, 102301, "2020/07/31 12:00:00", 2, 24003, 403, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", "2030/12/17 14:59:59", 24, "アサヒ", 0, 10046, 1.99, 192201, "2020/07/31 12:00:00", 2, 24004, 701, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", "2030/12/17 14:59:59", 24, "アサヒ", 0, 10046, 2.21, 192201, "2020/07/31 12:00:00", 1, 24005, 702, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", "2030/12/17 14:59:59", 24, "アサヒ", 0, 10046, 3.33, 192201, "2020/07/31 12:00:00", 2, 24006, 703, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", "2030/12/17 14:59:59", 24, "部員３", 0, 10046, 0, 192301, "2020/07/31 12:00:00", 2, 24007, 801, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", "2030/12/17 14:59:59", 24, "部員３", 0, 10046, 2.68, 192301, "2020/07/31 12:00:00", 1, 24008, 802, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", "2030/12/17 14:59:59", 24, "部員３", 0, 10046, 0, 192301, "2020/07/31 12:00:00", 2, 24009, 803, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("やった！", "2030/12/17 14:59:59", 24, "", 0, 10046, 0, 192501, "2020/07/31 12:00:00", 1, 24010, 501, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("勝ったよ！", "2030/12/17 14:59:59", 24, "", 0, 10046, 0, 192501, "2020/07/31 12:00:00", 1, 24011, 502, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("いい調子！", "2030/12/17 14:59:59", 24, "", 0, 10046, 0, 192501, "2020/07/31 12:00:00", 1, 24012, 503, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 5.33, 113501, "2020/07/31 12:00:00", 6, 24013, 111, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 6.85, 113501, "2020/07/31 12:00:00", 1, 24014, 112, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 3, 113501, "2020/07/31 12:00:00", 1, 24015, 113, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", "2030/12/17 14:59:59", 24, "ダイチ", 0, 10046, 6.11, 192401, "2020/07/31 12:00:00", 1, 24016, 611, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", "2030/12/17 14:59:59", 24, "ダイチ", 0, 10046, 6.75, 192401, "2020/07/31 12:00:00", 1, 24017, 612, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", "2030/12/17 14:59:59", 24, "ダイチ", 0, 10046, 0, 192401, "2020/07/31 12:00:00", 2, 24018, 613, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", "2030/12/17 14:59:59", 24, "ハツネ", 0, 10046, 4.52, 113401, "2020/07/31 12:00:00", 2, 24019, 211, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", "2030/12/17 14:59:59", 24, "ハツネ", 0, 10046, 3.89, 113401, "2020/07/31 12:00:00", 2, 24020, 212, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", "2030/12/17 14:59:59", 24, "ハツネ", 0, 10046, 13.49, 113401, "2020/07/31 12:00:00", 1, 24021, 213, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", "2030/12/17 14:59:59", 24, "カヤ", 0, 10046, 3.17, 106501, "2020/07/31 12:00:00", 1, 24022, 311, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", "2030/12/17 14:59:59", 24, "カヤ", 0, 10046, 4.42, 106501, "2020/07/31 12:00:00", 1, 24023, 312, 2, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", "2030/12/17 14:59:59", 24, "カヤ", 0, 10046, 2.89, 106501, "2020/07/31 12:00:00", 6, 24024, 313, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", "2030/12/17 14:59:59", 24, "アヤネ", 0, 10046, 3.71, 102301, "2020/07/31 12:00:00", 4, 24025, 421, 3, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", "2030/12/17 14:59:59", 24, "アサヒ", 0, 10046, 5.1, 192201, "2020/07/31 12:00:00", 2, 24026, 721, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", "2030/12/17 14:59:59", 24, "部員３", 0, 10046, 4.34, 192301, "2020/07/31 12:00:00", 1, 24027, 821, 3, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("いい勝負だったよ\nまたやろうね", "2030/12/17 14:59:59", 24, "", 0, 10046, 0, 192501, "2020/07/31 12:00:00", 1, 24028, 521, 1, 0);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 5.62, 113501, "2020/07/31 12:00:00", 1, 24029, 101, 2, -360);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 9.58, 113501, "2020/07/31 12:00:00", 1, 24030, 102, 2, -360);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 0, 113501, "2020/07/31 12:00:00", 2, 24031, 103, 2, -360);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 9.13, 113501, "2020/07/31 12:00:00", 2, 24032, 104, 1, -360);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES ("絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", "2030/12/17 14:59:59", 24, "ミサト", 0, 10046, 8.27, 113501, "2020/07/31 12:00:00", 1, 24033, 105, 2, -360);
